package org.apache.commons.jxpath.ri.axes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.axes.AttributeContext;
import org.apache.commons.jxpath.ri.axes.EvalContext;
import org.apache.commons.jxpath.ri.axes.NodeTest;
import org.apache.commons.jxpath.ri.compiler.NodeNameTest;
import org.apache.commons.jxpath.ri.compiler.NodeTest;
import org.apache.commons.jxpath.ri.model.NodeIterator;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Spy;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class AttributeContext_setPosition_TriageGen0Test {

    @Spy
    private EvalContext parentContext;
    @Spy
    private NodeTest nodeTest;
    private AttributeContext attributeContext;

    @Before
    public void setUp() {
        attributeContext = spy(new AttributeContext(parentContext, nodeTest));
    }

    /**
     * Test case: position is equal to current position.
     * Expected: No reset, while loop does not execute, returns true.
     */
    @Test
    public void testSetPosition_SameAsCurrent() {
        doReturn(5).when(attributeContext).getCurrentPosition();

        boolean result = attributeContext.setPosition(5);

        assertTrue(result);
        verify(attributeContext, never()).reset();
        verify(attributeContext, never()).nextNode();
    }

    /**
     * Test case: position is less than current position.
     * Expected: reset() is called, then while loop attempts to advance.
     * Since reset() usually sets position to 0, the loop will run.
     */
    @Test
    public void testSetPosition_LessThanCurrent_TriggersReset() {
        doReturn(10).when(attributeContext).getCurrentPosition();
        // After reset, let's assume position becomes 0
        doReturn(0).when(attributeContext).getCurrentPosition();
        // nextNode returns true once to reach position 1
        doReturn(true).doReturn(1).when(attributeContext).nextNode();
        // Mocking getCurrentPosition to return 1 after one nextNode call
        doReturn(0).when(attributeContext).getCurrentPosition();
        // We need to simulate the progression of getCurrentPosition()
        // Because getCurrentPosition() is called in the while condition
        doReturn(0, 1).when(attributeContext).getCurrentPosition();

        boolean result = attributeContext.setPosition(1);

        assertTrue(result);
        verify(attributeContext).reset();
    }

    /**
     * Test case: position is greater than current position and nextNode succeeds.
     * Expected: while loop executes, nextNode returns true, returns true.
     */
    @Test
    public void testSetPosition_GreaterThanCurrent_Success() {
        doReturn(0).when(attributeContext).getCurrentPosition();
        // Simulate progressing: 0 -> 1 -> 2
        doReturn(0, 1, 2).when(attributeContext).getCurrentPosition();
        doReturn(true, true).when(attributeContext).nextNode();

        boolean result = attributeContext.setPosition(2);

        assertTrue(result);
        verify(attributeContext, never()).reset();
        verify(attributeContext, times(2)).nextNode();
    }

    /**
     * Test case: position is greater than current position but nextNode fails.
     * Expected: while loop executes, nextNode returns false, returns false.
     */
    @Test
    public void testSetPosition_GreaterThanCurrent_NextNodeFails() {
        doReturn(0).when(attributeContext).getCurrentPosition();
        doReturn(0, 1).when(attributeContext).getCurrentPosition();
        doReturn(false).when(attributeContext).nextNode();

        boolean result = attributeContext.setPosition(2);

        assertFalse(result);
        verify(attributeContext, never()).reset();
        verify(attributeContext).nextNode();
    }

    /**
     * Test case: position is less than current position and nextNode fails immediately.
     * Expected: reset() is called, nextNode returns false, returns false.
     */
    @Test
    public void testSetPosition_LessThanCurrent_AndNextNodeFails() {
        doReturn(5).when(attributeContext).getCurrentPosition();
        // After reset, position is 0
        doReturn(0).when(attributeContext).getCurrentPosition();
        doReturn(false).when(attributeContext).nextNode();

        boolean result = attributeContext.setPosition(10);

        assertFalse(result);
        verify(attributeContext).reset();
    }
}
